'use strict';
(() => {
const KEY='jacobs-baymax-365-r02';
let D,S,view='day',selected=1,planQuery='',planPhase='',planStatus='',planMonth='',registryQuery='',registry='requirements',toastTimer,storageOK=true;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={day:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m8 12 3 3 5-6"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h1m6 0h1m-8 4h1m6 0h1"/>',roadmap:'<path d="M5 20V4m0 1h13l-3 4 3 4H5m3 7h11"/>',reviews:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',resources:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8m-8 4h8"/>',controls:'<path d="M4 20V10m8 10V4m8 16v-7M1 10h6m2-6h6m2 9h6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.resources}</svg>`;
const money=v=>typeof v==='number'&&Number.isFinite(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v):'Not entered';
const num=(v,p=1)=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(p):'Not entered';
const fmtDate=date=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(date);
const parseDate=s=>{const [y,m,d]=String(s).split('-').map(Number);return new Date(y,m-1,d,12);};
const isoDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateAt=(n,start=S.start)=>{const d=parseDate(start);d.setDate(d.getDate()+n-1);return d;};
const todayISO=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const calendarDay=()=>{const a=parseDate(S.start),b=parseDate(todayISO());return Math.max(1,Math.min(365,1+Math.round((Date.UTC(b.getFullYear(),b.getMonth(),b.getDate())-Date.UTC(a.getFullYear(),a.getMonth(),a.getDate()))/86400000)));};
const months=()=>Array.from({length:12},(_,i)=>{const start=parseDate(S.start);const make=k=>{const y=start.getFullYear(),m=start.getMonth()+k;return new Date(y,m,Math.min(start.getDate(),new Date(y,m+1,0).getDate()),12);};const a=make(i),b=make(i+1);b.setDate(b.getDate()-1);const dayDiff=x=>1+Math.round((Date.UTC(x.getFullYear(),x.getMonth(),x.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000);return {id:i+1,start:Math.max(1,dayDiff(a)),end:Math.min(365,dayDiff(b)),a,b};});
function blankState(){return {version:2,start:D.meta.defaultStart,days:{},gates:{},stages:{},costs:Object.fromEntries(D.budget.map(r=>[r[0],{forecast:r[0]==='B-01'?8899:r[2]*r[3],actual:null,kind:r[0]==='B-14'?'reserve':'allowance',reference:'',updated:''}])),masses:Object.fromEntries(D.mass.map(r=>[r[0],{estimate:null,measured:null,reference:'',updated:''}]))};}
function dayState(n){return S.days[n]||(S.days[n]={steps:Array(6).fill(false),checks:Array(3).fill(false),notes:'',result:'',evidence:'',reviewer:'',hours:'',recordedAt:'',history:[]});}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;}catch{storageOK=false;$('storage-caption').textContent='Browser storage unavailable. Export a backup before leaving.';}}
function load(){const init=blankState();try{const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(x.version===2&&validDate(x.start)){Object.assign(init,{start:x.start,days:x.days||{},gates:x.gates||{},stages:x.stages||{}});for(const [id,r]of Object.entries(x.costs||{}))if(id in init.costs)init.costs[id]={...init.costs[id],...r};for(const [id,r]of Object.entries(x.masses||{}))if(id in init.masses)init.masses[id]={...init.masses[id],...r};}}}catch{storageOK=false;}return init;}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&isoDate(parseDate(s))===s;}
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
const dayCount=()=>Object.values(S.days).filter(r=>r.result==='PASS').length;
function budgetTotals(){const a=Object.values(S.costs);return {forecast:a.every(r=>Number.isFinite(r.forecast))?a.reduce((s,r)=>s+Math.max(r.forecast,Number.isFinite(r.actual)?r.actual:0),0):null,actual:a.every(r=>Number.isFinite(r.actual))?a.reduce((s,r)=>s+r.actual,0):null};}
function massTotals(){const a=Object.values(S.masses);return {estimate:a.every(r=>Number.isFinite(r.estimate))?a.reduce((s,r)=>s+r.estimate,0):null,measured:a.every(r=>Number.isFinite(r.measured))?a.reduce((s,r)=>s+r.measured,0):null};}
function recordComplete(r){return !!r&&r.result==='PASS'&&r.reviewed===true&&r.checks?.every(Boolean)&&!!r.reviewer?.trim()&&!!r.role?.trim()&&!!r.evidence?.trim()&&validDate(r.date);}
function gateIssues(id){const g=D.gates.find(g=>g.id===id);if(!g)return ['Unknown gate'];const issues=[];for(const p of g.requires)if(!gateSatisfied(p))issues.push(`${p} has no applicable recorded release`);for(const p of g.stages)if(!stageSatisfied(p))issues.push(`${p} has no applicable accepted test record`);if(id==='G3'){const b=budgetTotals(),m=massTotals();if(b.forecast===null||b.forecast>10000)issues.push('Complete projected cash cost must fit the USD 10000 ceiling');if(b.actual===null)issues.push('Confirm actual spending, including real zeros, on every budget line');if(Object.values(S.costs).some(r=>!['quote','receipt','confirmed resource','reserve'].includes(r.kind)||!r.reference?.trim()))issues.push('Replace unquoted allowances with traceable costs/resources and a documented reserve');if(m.estimate===null)issues.push('Enter all 13 projected mass contributions with source references');else if(m.estimate>55)issues.push(`Projected mass ${m.estimate.toFixed(2)} kg exceeds the 55 kg target and needs rework`);if(Object.values(S.masses).some(r=>!r.reference?.trim()))issues.push('Every mass contribution needs a source reference');}return issues;}
function gateSatisfied(id,trail=[]){if(trail.includes('G:'+id))return false;const g=D.gates.find(x=>x.id===id);if(!g||!recordComplete(S.gates[id]))return false;const next=[...trail,'G:'+id];if(!g.requires.every(x=>gateSatisfied(x,next))||!g.stages.every(x=>stageSatisfied(x,next)))return false;if(id==='G3'){const b=budgetTotals(),m=massTotals();if(b.forecast===null||b.forecast>10000||b.actual===null||m.estimate===null||m.estimate>55)return false;if(Object.values(S.costs).some(r=>!['quote','receipt','confirmed resource','reserve'].includes(r.kind)||!r.reference?.trim()))return false;if(Object.values(S.masses).some(r=>!r.reference?.trim()))return false;}return true;}
function stageSatisfied(id,trail=[]){if(trail.includes('S:'+id))return false;const s=D.stages.find(x=>x.id===id);if(!s||!recordComplete(S.stages[id]))return false;const next=[...trail,'S:'+id];return gateSatisfied(s.gate,next)&&s.requires.every(x=>stageSatisfied(x,next));}
function readiness(d){const issues=[];for(const g of d.gates)if(!gateSatisfied(g))issues.push(`${g}: ${D.gates.find(x=>x.id===g)?.name} — no applicable release recorded`);for(const s of d.stages)if(!stageSatisfied(s))issues.push(`${s}: ${D.stages.find(x=>x.id===s)?.name} — prior test not accepted`);const mass=massTotals();if((d.gates.length||d.stages.length)&&mass.estimate>65)issues.push('Projected mass exceeds 65 kg: major design review required before progression');return issues;}
function pill(result){if(result==='PASS')return '<span class="pill green">PASS · task recorded</span>';if(result==='BLOCKED')return '<span class="pill red">BLOCKED</span>';if(result==='REWORK')return '<span class="pill amber">REWORK</span>';return '<span class="pill">Planned</span>';}
function route(){const [v,n]=location.hash.slice(1).split('/');view=['day','plan','roadmap','reviews','resources','controls','settings','register'].includes(v)?v:'day';if(view==='day')selected=Math.max(1,Math.min(365,Number(n)||1));if(view==='register')registry=['requirements','hazards','verification'].includes(n)?n:'requirements';render();}
function navigate(hash){if(location.hash===hash){route();window.scrollTo(0,0);}else location.hash=hash;$('main').focus({preventScroll:true});document.querySelector('.sidebar').classList.remove('open');}
function render(){const active=view==='register'?'resources':view;const nav=[['day','Daily workspace',''],['plan','All 365 days','365'],['roadmap','Year roadmap','12'],['reviews','Reviews & test stages','25'],['controls','Budget & mass',''],['resources','Project library','']];$('navigation').innerHTML=nav.map(([v,t,c])=>`<a class="nav-link ${active===v?'active':''}" ${active===v?'aria-current="page"':''} href="#${v}${v==='day'?'/'+selected:''}">${icon(v)}<span>${t}</span>${c?`<span class="nav-count">${c}</span>`:''}</a>`).join('');$('top-section').textContent=nav.find(x=>x[0]===active)?.[1]||'Settings';updateSide();$('main').innerHTML=({day:renderDay,plan:renderPlan,roadmap:renderRoadmap,reviews:renderReviews,controls:renderControls,resources:renderResources,settings:renderSettings,register:renderRegister}[view])();bindView();}
function updateSide(){const count=dayCount();$('side-progress').innerHTML=`${count} <span>/ 365 days</span>`;$('side-meter').style.width=(count/365*100)+'%';if(!storageOK)$('storage-caption').textContent='Storage is unavailable. Export a backup before leaving.';}
const heading=(eyebrow,title,description,tools='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="head-description">${description}</p></div>${tools?`<div class="head-tools">${tools}</div>`:''}</div>`;
function renderDay(){const d=D.days[selected-1],r=dayState(selected),issues=readiness(d),done=r.steps.filter(Boolean).length;const first=(d.week-1)*7+1;const weekDays=D.days.filter(x=>x.week===d.week);const isConditional=!!(d.gates.length||d.stages.length);return heading(`WEEK ${String(d.week).padStart(2,'0')} · ${esc(d.phase)} · ${fmtDate(dateAt(d.id))}`,`<span style="font-weight:400;color:#94a28e">${String(d.id).padStart(3,'0')}.</span> ${esc(d.title)}`,esc(d.weekTitle),`<button class="button ghost small" data-action="today">Calendar day ${calendarDay()}</button><button class="button ghost small" data-action="download-day">${icon('download')}Save checklist</button>`)+`
 <div class="overview-strip"><div class="overview-cell"><div class="stat-label">TODAY'S WORK</div><div class="stat-value">${Math.floor(d.minutes/60)}h ${d.minutes%60?d.minutes%60+'m':''}<em>planned</em></div><div class="stat-note">Adjust around real reviews and availability</div></div><div class="overview-cell"><div class="stat-label">TASK OUTCOME</div><div style="margin-top:8px">${pill(r.result)}</div><div class="stat-note">Recorded separately from engineering release</div></div><div class="overview-cell"><div class="stat-label">YOUR YEAR</div><div class="stat-value">${dayCount()}<em>/ 365 tasks recorded</em></div><div class="stat-note">${Math.round(dayCount()/365*100)}% of daily task records</div></div><div class="overview-cell"><div class="stat-label">REVIEWED TEST STAGES</div><div class="stat-value">${D.stages.filter(x=>stageSatisfied(x.id)).length}<em>/ 16 accepted records</em></div><div class="stat-note">Independent evidence still required</div></div></div>
 ${issues.length?`<div class="notice"><strong>This day is conditional. ${issues.length} prerequisite${issues.length===1?' is':'s are'} missing.</strong><ul class="blocker-list">${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>Read the plan now. Use the specific desk-work alternative below; do not purchase, fabricate or run tests outside an actual release. <a href="#reviews">Review prerequisites →</a></div>`:''}
 <div class="day-layout"><div class="day-primary"><section class="panel"><div class="panel-heading"><h2>Do this, in order</h2><div class="progress-line"><div class="meter"><span style="width:${done/6*100}%"></span></div><span id="task-count">${done} of 6 steps</span></div></div>${d.steps.map((s,i)=>`<label class="task-step ${r.steps[i]?'done':''}" for="step-${i}"><input id="step-${i}" type="checkbox" data-step="${i}" ${r.steps[i]?'checked':''}><span class="step-copy"><span class="step-meta"><span class="step-number">STEP ${String(i+1).padStart(2,'0')}</span><span class="step-time">${d.stepMinutes[i]} MIN</span></span><p>${esc(s)}</p></span></label>`).join('')}</section>
 <section class="panel"><div class="panel-heading"><h2>Before you call this day complete</h2><span class="count">Evidence first</span></div><div class="panel-body">${d.acceptance.map((a,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${r.checks[i]?'checked':''}><span>${esc(a)}</span></label>`).join('')}<details class="stop-details"><summary>Stop conditions for this task</summary><p>${esc(d.stop)}</p></details>${issues.length?`<div class="alternative"><h3>If you are blocked today, do this instead</h3><ol>${d.alternative.map(a=>`<li>${esc(a)}</li>`).join('')}</ol><p>Save <code>${esc(d.alternativeOutput)}</code>. Record the original task as BLOCKED with your alternative evidence; it does not count as a physical PASS.</p></div>`:''}</div></section>
 <section class="panel notes-panel"><div class="panel-body"><div class="notes-label"><h3>Your working notes</h3><small class="muted-small" id="notes-saved">Saved locally as you type</small></div><textarea id="day-notes" aria-label="Working notes" placeholder="What did you actually do? What is still unknown? Use fictional data only.">${esc(r.notes)}</textarea><p class="muted-small" style="margin-top:7px">Keep real patient information, secrets and credentials out of this tracker.</p></div></section>
 <section class="panel"><div class="panel-heading"><h2>Record the day's outcome</h2><span class="count">No automatic PASS</span></div><div class="panel-body">${r.result?`<div class="saved-outcome ${r.result!=='PASS'?'blocked':''}"><strong>${esc(r.result)}</strong> · ${esc(r.recordedAt?fmtDate(parseDate(r.recordedAt.slice(0,10))):'Recorded')}<div class="outcome-meta">Evidence: ${esc(r.evidence)}${r.reviewer?' · Role/reviewer: '+esc(r.reviewer):''}</div></div>`:''}<form id="day-outcome"><div class="outcome-grid"><label><span class="field-label">Result</span><select name="result" required><option value="">Choose an outcome</option>${['PASS','REWORK','BLOCKED'].map(x=>`<option ${r.result===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="field-label">Actual evidence reference</span><input name="evidence" value="${esc(r.evidence)}" placeholder="File path, run ID or review record" required maxlength="1500"></label><label><span class="field-label">Time actually spent in hours</span><input name="hours" type="number" min="0" max="24" step="0.25" value="${esc(r.hours)}" placeholder="2.5"></label><label><span class="field-label">Your role or actual reviewer / permit reference</span><input name="reviewer" value="${esc(r.reviewer)}" placeholder="Required for conditional physical work" maxlength="1000"></label></div><p class="form-error" id="outcome-error" role="alert"></p><div class="save-row"><button class="button" type="submit">Record outcome ${icon('arrow')}</button><small class="muted-small">${isConditional?'A calendar date cannot authorize this work.':'This records the task, not a whole-system validation.'}</small></div></form></div></section></div>
 <aside class="day-aside"><section class="panel"><div class="side-section"><div class="eyebrow">DAY ${String(d.id).padStart(3,'0')} / 365</div><h3 style="margin-top:8px">${esc(d.weekTitle)}</h3><div class="mini-week">${weekDays.map(x=>`<a class="mini-day ${x.id===selected?'selected':dayState(x.id).result==='PASS'?'passed':dayState(x.id).result?'blocked':''}" href="#day/${x.id}" aria-label="Day ${x.id}: ${esc(x.title)}" ${x.id===selected?'aria-current="date"':''}>${x.id}</a>`).join('')}</div><div class="side-row"><span>Work mode</span><strong>${esc(d.mode)}</strong></div><div class="side-row"><span>Owner</span><strong>Faisal Farouq</strong></div><div class="side-row"><span>Revision</span><strong>R0.2 · provisional plan</strong></div></div><div class="side-section"><h3>Save this deliverable</h3><div class="output-file">${esc(d.output)}</div><button class="button text small" data-action="copy-output">Copy file path</button><p>Create the deliverable in your project tools. This website stores checklist and evidence references; it does not fabricate files or execute robot tests.</p></div><div class="daily-nav"><a class="button ghost small ${selected===1?'hidden':''}" href="#day/${selected-1}">← Previous</a><a class="button ghost small ${selected===365?'hidden':''}" href="#day/${selected+1}">Next day →</a></div></section><section class="panel"><div class="side-section"><h3>Inputs you need</h3><ul>${d.inputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="side-section"><h3>Calculation or exact check</h3><p>${esc(d.calculation)}</p></div><div class="side-section"><h3>Linked requirements</h3><div class="tag-list">${d.requirements.map(x=>`<button class="tag" data-action="requirement" data-id="${x}">${x}</button>`).join('')}</div><div class="next-box"><strong>Next dependency</strong>${esc(d.next)}</div></div></section></aside></div>`;}
function renderPlan(){return heading('THE COMPLETE YEAR','Every day has a specific job.','365 unique daily objectives, 2,190 ordered steps and a named deliverable for every day. Read ahead freely. Gates and actual evidence determine physical readiness.',`<a class="button ghost small" href="resources/Baymax_365_Daily_Plan.csv" download>${icon('download')}Download all 365 days</a>`)+`<div class="search-tools"><label class="search-field">${icon('search')}<input id="plan-search" aria-label="Search the daily plan" value="${esc(planQuery)}" placeholder="Search a day, task, output or requirement…"></label><select id="plan-phase" aria-label="Filter by workstream"><option value="">All workstreams</option>${Object.keys(D.phaseDescriptions).map(x=>`<option ${planPhase===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="plan-status" aria-label="Filter by task outcome"><option value="">All outcomes</option>${['Planned','PASS','REWORK','BLOCKED'].map(x=>`<option ${planStatus===x?'selected':''}>${x}</option>`).join('')}</select><select id="plan-month" aria-label="Filter by project month"><option value="">All project months</option>${months().map(x=>`<option value="${x.id}" ${String(x.id)===planMonth?'selected':''}>Month ${x.id} · Days ${x.start}–${x.end}</option>`).join('')}</select></div><div id="plan-results">${planResults()}</div>`;}
function filteredDays(){const q=planQuery.toLowerCase().trim(),m=months().find(x=>String(x.id)===planMonth);return D.days.filter(d=>(!q||`${d.id} ${d.title} ${d.steps.join(' ')} ${d.output} ${d.requirements.join(' ')}`.toLowerCase().includes(q))&&(!planPhase||d.phase===planPhase)&&(!planStatus||(dayState(d.id).result||'Planned')===planStatus)&&(!m||(d.id>=m.start&&d.id<=m.end)));}
function planResults(){const list=filteredDays();if(!list.length)return '<div class="panel empty">No days match those filters. Try a different word or clear a filter.</div>';const weeks=[...new Set(list.map(d=>d.week))];return `<p class="muted-small" style="margin-bottom:13px">${list.length} days shown · ${planQuery?'Matching exact instructions and deliverables':'Expand a week to see its seven daily objectives'}</p>`+weeks.map(w=>{const days=list.filter(d=>d.week===w);return `<details class="week-card" ${planQuery||planPhase||planStatus||planMonth||w===1?'open':''}><summary><span class="week-index">W${String(w).padStart(2,'0')}</span><h3>${esc(days[0].weekTitle)}</h3><span class="week-caption">${esc(days[0].phase)} · Days ${days[0].id}–${days.at(-1).id}</span><span class="week-arrow">›</span></summary>${days.map(d=>`<button class="plan-day" data-action="open-day" data-day="${d.id}"><span class="day-index">${String(d.id).padStart(3,'0')}</span><span><strong>${esc(d.title)}</strong><small>${fmtDate(dateAt(d.id))} · ${esc(d.output.split('/').at(-1))}</small></span><span class="day-length">${dayState(d.id).result||`${d.minutes/60} h · 6 steps`}</span><span style="color:#90a181">↗</span></button>`).join('')}</details>`;}).join('');}
function renderRoadmap(){return heading('365 DAYS · 52 WEEKS + CLOSEOUT','A year with clear dependencies.',`Start ${fmtDate(parseDate(S.start))} · Finish ${fmtDate(dateAt(365))}. Approximately ${D.meta.ownerHours} planned owner-hours, plus qualified specialist and fabrication effort. Dates are targets; unresolved gates can extend the schedule.`,`<a class="button ghost small" href="#settings">Change start date</a>`)+`<div class="notice neutral"><strong>What this plan can do:</strong> tell you the next concrete task, preserve evidence and make blockers visible. Completing calendar tasks cannot guarantee a feasible full-size biped or a USD 10000 build.</div><div class="roadmap-grid">${months().map(m=>{const list=D.days.filter(x=>x.id>=m.start&&x.id<=m.end),phases=[...new Set(list.map(x=>x.phase))],count=list.filter(x=>dayState(x.id).result==='PASS').length;return `<article class="roadmap-card"><div class="eyebrow">MONTH ${String(m.id).padStart(2,'0')} · DAYS ${m.start}–${m.end}</div><h3>${esc(phases.join(' & '))}</h3><p>${fmtDate(m.a)} – ${fmtDate(dateAt(m.end))}<br>${esc(D.phaseDescriptions[phases[0]])}</p><div class="meter"><span style="width:${count/list.length*100}%"></span></div><div class="bottom"><span>${count}/${list.length} daily tasks recorded</span><button class="button text small" data-action="month" data-month="${m.id}">Open month →</button></div></article>`;}).join('')}</div><div class="section-heading"><h2>The seven non-negotiable limits</h2></div><div class="panel panel-body"><div class="phase-summary">${['1.829 m height target','55 kg operating mass target','>65 kg major design review','10 active lower-body joints','Two separate 3-step tethered trials','2 kg × 10 stationary supported repetitions','USD 10000 cash ceiling'].map(x=>`<span class="pill">${x}</span>`).join('')}</div><p class="section-description" style="margin-bottom:0">Fictional care data only. No diagnosis, treatment/dose advice, dispensing, person support, cargo walking or unapproved public operation. Conversational AI has no safety bypass.</p></div>`;}
function reviewCard(kind,x){const ok=kind==='gate'?gateSatisfied(x.id):stageSatisfied(x.id),r=S[kind==='gate'?'gates':'stages'][x.id],label=ok?'Recorded release':r?.result==='PASS'?'Prerequisites changed':r?.result||'Not reviewed';return `<article class="review-card"><div class="review-top"><span class="review-id">${x.id}</span><span class="pill ${ok?'green':r?.result?'amber':''}">${esc(label)}</span></div><h3>${esc(x.name)}</h3><p>Target Day ${x.day} · ${fmtDate(dateAt(x.day))}<br>${kind==='gate'?`Prerequisites: ${esc([...x.requires,...x.stages].join(', ')||'Owner baseline')}`:`Requires ${esc([x.gate,...x.requires].join(', '))}`}${r?.reviewer?`<br>Actual reviewer: ${esc(r.reviewer)}`:''}</p><button class="button ghost small" data-action="review" data-kind="${kind}" data-id="${x.id}">${r?'View / update record':'Record actual review'} →</button></article>`;}
function renderReviews(){return heading('ACTUAL REVIEW RECORDS','A gate is evidence, not a date.','Record decisions made by the actual qualified people. The website checks prerequisites and stores your references; it cannot inspect equipment, assess competence, issue permits or certify a robot.')+`<div class="notice"><strong>All releases begin pending.</strong> Checking daily tasks does not unlock hardware. A release needs real reviewed evidence, an exact scope and named authority. If a prerequisite changes, a recorded release may stop applying.</div><div class="section-heading"><h2>9 project release gates</h2><span class="days-covered">${D.gates.filter(x=>gateSatisfied(x.id)).length} applicable recorded releases</span></div><div class="review-grid">${D.gates.map(x=>reviewCard('gate',x)).join('')}</div><div class="section-heading"><h2>16 test stages, in the required order</h2><span class="days-covered">${D.stages.filter(x=>stageSatisfied(x.id)).length} accepted records</span></div><div class="review-grid">${D.stages.map(x=>reviewCard('stage',x)).join('')}</div>`;}
function renderResources(){return heading('PROJECT LIBRARY','The baseline, within reach.','Download the original connected package or inspect its requirements, risks and verification plans. These are R0.1 source records; your daily/review records do not silently rewrite them.')+`<div class="document-grid">${[
 ['One-page mission','The project outcome, limits and exclusions in one page.','Jacobs_Baymax_Mission_R0_1.pdf','Read mission PDF'],
 ['Engineering baseline','All 12 connected artifacts with architecture, calculations and review gates.','Jacobs_Baymax_Engineering_Baseline_R0_1.pdf','Open engineering PDF'],
 ['Editable control workbook','Requirements, budgets, mass model, verification, risks and decisions.','Jacobs_Baymax_Control_Workbook_R0_1.xlsx','Download workbook'],
 ['Complete original project package','Editable report, source registers, fictional fixtures and organized project folders.','Jacobs_Baymax_Complete_Package_R0_1.zip','Download complete ZIP'],
 ['All 365 daily plans','Every daily objective, step, check, stop condition, output and dependency.','Baymax_365_Daily_Plan.csv','Download 365-day CSV']
 ].map(([t,p,f,l])=>`<article class="document-card"><span class="doc-icon">${icon('resources')}</span><div><h3>${t}</h3><p>${p}</p><a href="resources/${f}" ${f.endsWith('.pdf')?'target="_blank" rel="noopener"':'download'}>${l} ↗</a></div></article>`).join('')}</div><div class="section-heading"><h2>Browse the original registers</h2></div><div class="button-row"><a class="button ghost" href="#register/requirements">64 requirements</a><a class="button ghost" href="#register/hazards">20 hazards & ethical risks</a><a class="button ghost" href="#register/verification">26 verification protocols</a></div><div class="section-heading"><h2>The 12 connected artifacts</h2></div><div class="artifact-list">${D.artifacts.map(a=>`<button class="artifact-button" data-action="artifact" data-id="${a.number}"><span>${String(a.number).padStart(2,'0')}</span>${esc(a.title)}<span style="margin-left:auto">↗</span></button>`).join('')}</div><div class="section-heading"><h2>Sources and scope</h2></div><div class="panel panel-body">${D.sources.map(s=>`<div class="source-item"><strong>${esc(s[0]+' · '+s[1])}</strong>${s[2].startsWith('https:')?`<a href="${esc(s[2])}" target="_blank" rel="noopener">Official source ↗</a> · `:''}Checked ${esc(s[4])}<br>${esc(s[5])}</div>`).join('')}</div>`;}
function renderRegister(){const title={requirements:'Requirement matrix',hazards:'Hazards and ethical risks',verification:'Verification protocols'}[registry];return heading('ORIGINAL R0.1 SOURCE REGISTER',title,'These source records remain unvalidated. Stage/review outcomes are recorded separately and need applicable actual evidence.',`<a class="button ghost small" href="resources/${registry==='requirements'?'Requirements':registry==='hazards'?'Hazards':'Verification'}_R0_1.csv" download>Download register</a>`)+`<div class="search-tools"><label class="search-field">${icon('search')}<input id="register-search" aria-label="Search source register" value="${esc(registryQuery)}" placeholder="Search an ID, requirement, hazard or protocol…"></label><a class="button ghost" href="#resources">Back to library</a></div><div class="panel panel-body" id="register-results">${registerResults()}</div>`;}
function registerResults(){const rows=D[registry].filter(r=>r.join(' ').toLowerCase().includes(registryQuery.toLowerCase()));if(!rows.length)return '<div class="empty">No matching records.</div>';return rows.map(r=>`<article class="register-record"><h3>${esc(r[0])} · ${esc(registry==='requirements'?r[1]:r[1])}</h3>${registry==='requirements'?`<p>${esc(r[2])}</p><div class="tag-list"><span class="tag">${esc(r[3])}</span><span class="tag">${esc(r[4]||'No hazard link')}</span><span class="tag">R0.1: NOT TESTED</span></div>`:registry==='hazards'?`<p><strong>Credible harm:</strong> ${esc(r[2])}<br><strong>Controls:</strong> ${esc(r[6])}<br><strong>Reviewer:</strong> ${esc(r[9])}<br><strong>Residual risk:</strong> UNASSESSED</p><div class="tag-list"><span class="tag">${esc(r[4])}</span><span class="tag">${esc(r[7])}</span><span class="tag">${esc(r[8])}</span></div>`:`<p><strong>Method:</strong> ${esc(r[2])}<br><strong>Acceptance:</strong> ${esc(r[3])}<br><strong>Prerequisites:</strong> ${esc(r[4])}<br><strong>Original blocker:</strong> ${esc(r[5])}</p><div class="tag-list"><span class="tag">${esc(r[6])}</span><span class="tag">R0.1: NOT EXECUTED</span></div>`}</article>`).join('');}
function renderControls(){const b=budgetTotals(),m=massTotals(),over=b.forecast===null?null:b.forecast-10000;return heading('KEEP THE CONSTRAINTS VISIBLE','Budget and mass, without hidden zeros.','Enter current project figures with sources. The original ceiling allowances are reference inputs, not qualified quotes. Missing actuals or mass values stay unknown.')+`<div class="controls-stats"><div class="control-stat"><div class="stat-label">CASH CEILING</div><div class="stat-value">$10,000</div><p>Unchanged Year 1 cap. No website action authorizes spending.</p></div><div class="control-stat"><div class="stat-label">CURRENT PROJECTED CASH</div><div class="stat-value">${money(b.forecast)}</div><p>${over>0?money(over)+' above the cap.':over===null?'Missing cost inputs.':'Within the numerical cap; technical qualification and review remain separate.'} Initial values use the dated R0.1 reference.</p></div><div class="control-stat"><div class="stat-label">ACTUAL CASH RECORDED</div><div class="stat-value">${money(b.actual)}</div><p>Enter every line, including confirmed zeros, before a complete actual-spend total is shown.</p></div></div>${over>0?`<div class="notice red"><strong>Procurement cost conflict:</strong> ${money(b.forecast)} projected against ${money(10000)}. G3 cannot apply until costs/resources, mass and actual qualified approval are reconciled.</div>`:''}<div class="section-heading"><h2>Cash forecast and commitments</h2><span class="days-covered">USD · projected totals include spending to date</span></div><div class="table-scroll"><table><thead><tr><th>Budget line</th><th>Projected total</th><th>Actual cash</th><th>Basis / reference</th><th></th></tr></thead><tbody>${D.budget.map(r=>{const x=S.costs[r[0]];return `<tr><td>${esc(r[0])} · ${esc(r[1])}<small>${esc(r[4])}</small></td><td class="number">${money(x.forecast)}</td><td class="number">${money(x.actual)}</td><td>${esc(x.kind)}<small>${esc(x.reference||'No current quote/resource reference entered')}</small></td><td><button class="button ghost small" data-action="cost" data-id="${r[0]}">Update</button></td></tr>`;}).join('')}</tbody></table></div><div class="section-heading"><h2>Operating mass</h2><span class="days-covered">Battery, panels and attached modules included</span></div><div class="controls-stats"><div class="control-stat"><div class="stat-label">TARGET / MAJOR REVIEW</div><div class="stat-value">55 <em style="font-size:14px">/ 65 kg</em></div><p>Above 55 kg requires rework. Above 65 kg triggers a major design review.</p></div><div class="control-stat"><div class="stat-label">CURRENT PROJECTED COMPONENT MASS</div><div class="stat-value">${m.estimate===null?'Incomplete':num(m.estimate,2)+' kg'}</div><p>${m.estimate===null?'Enter all 13 contributions. Allocations are not predictions.':m.estimate>65?'Major design review required.':m.estimate>55?'Above target; rework required.':'Numerical target met; source/model review remains required.'}</p></div><div class="control-stat"><div class="stat-label">MEASURED COMPONENT MASS</div><div class="stat-value">${m.measured===null?'Incomplete':num(m.measured,2)+' kg'}</div><p>Component sums support reconciliation; full configuration weighing and calibration still need evidence.</p></div></div><div class="table-scroll"><table><thead><tr><th>Onboard subsystem</th><th>R0.1 allocation kg</th><th>Projected kg</th><th>Measured kg</th><th></th></tr></thead><tbody>${D.mass.map(r=>{const x=S.masses[r[0]];return `<tr><td>${esc(r[0])} · ${esc(r[1])}<small>${esc(x.reference||'No current mass source entered')}</small></td><td class="number">${num(r[2],2)}</td><td class="number">${num(x.estimate,2)}</td><td class="number">${num(x.measured,2)}</td><td><button class="button ghost small" data-action="mass" data-id="${r[0]}">Update</button></td></tr>`;}).join('')}</tbody></table></div><p class="section-description">Original allocation: 47.8 kg components + 7.2 kg unassigned growth reserve = 55 kg. Reserve is headroom, not hardware; do not add it a second time to grown component estimates. The 2 kg object and external fixture are separately accounted, and the object is never carried while walking.</p>`;}
function renderSettings(){return heading('MAKE THE PLAN YOURS','Project settings and backups.','Your checklist, notes, evidence references and review records stay in this browser on this website. They do not synchronize across devices automatically.')+`<section class="panel"><div class="panel-body"><div class="settings-section"><h2>Project start date</h2><p>Changing the date shifts calendar labels only. It preserves records and never releases a gate or marks a day complete.</p><form id="settings-form"><label><span class="field-label">Day 1 date</span><input name="start" type="date" value="${esc(S.start)}" required min="2020-01-01" max="2100-12-31"></label><p>Day 365: <strong>${fmtDate(dateAt(365))}</strong> · Planned owner effort: ${D.meta.ownerHours} hours. Most days 2 h 30 min; weekly reviews and closeout 2 h.</p><div class="button-row"><button class="button" type="submit">Save start date</button><button class="button ghost" type="button" data-action="today">Open calendar day</button></div></form></div><div class="settings-section"><h2>Keep a recoverable backup</h2><p>Export after each weekly review and before changing browsers or devices. The backup contains your notes and self-recorded reviews; keep it private. Importing replaces this browser's current records only after confirmation.</p><div class="button-row"><button class="button ghost" data-action="backup">Export progress JSON</button><button class="button ghost" data-action="import">Import a backup</button><a class="button ghost" href="resources/Baymax_365_Daily_Plan.csv" download>Download all daily instructions</a></div></div><div class="settings-section"><h2>What the tracker does</h2><p>It stores your planning and evidence references and checks that prerequisite records exist. It does not contact caregivers/vendors, write fabrication files, validate credentials, inspect equipment, execute robot commands or issue professional approvals. Use fictional care data only.</p><p>Accountable owner: Faisal Farouq. Daily planner revision R0.2, based on R0.1 dated 23 October 2026. Budget feasibility and physical completion remain unproven.</p></div></div></section>`;}
function bindView(){if(view==='day'){$('day-notes').addEventListener('input',e=>{dayState(selected).notes=e.target.value;persist();$('notes-saved').textContent=storageOK?'Saved in this browser':'Export a backup — storage unavailable';});$('day-outcome').addEventListener('submit',saveDay);}if(view==='plan'){for(const [id,key]of [['plan-search','q'],['plan-phase','phase'],['plan-status','status'],['plan-month','month']])$(id).addEventListener(id==='plan-search'?'input':'change',e=>{if(key==='q')planQuery=e.target.value;if(key==='phase')planPhase=e.target.value;if(key==='status')planStatus=e.target.value;if(key==='month')planMonth=e.target.value;$('plan-results').innerHTML=planResults();});}if(view==='register')$('register-search').addEventListener('input',e=>{registryQuery=e.target.value;$('register-results').innerHTML=registerResults();});if(view==='settings')$('settings-form').addEventListener('submit',e=>{e.preventDefault();const start=new FormData(e.target).get('start');if(!validDate(start))return toast('Enter a valid start date.');S.start=start;persist();render();toast('Calendar shifted. Your existing records are unchanged.');});}
function saveDay(e){e.preventDefault();const f=new FormData(e.target),d=D.days[selected-1],r=dayState(selected),result=f.get('result'),evidence=f.get('evidence').trim(),reviewer=f.get('reviewer').trim();const errors=[];if(result==='PASS'){if(!r.steps.every(Boolean)||!r.checks.every(Boolean))errors.push('Complete all six steps and all three evidence checks before recording PASS.');if(readiness(d).length)errors.push('Required prior releases are missing or no longer applicable. Record BLOCKED and use the desk-work alternative.');if((d.gates.length||d.stages.length)&&!reviewer)errors.push('Record the actual role/reviewer and signed permit reference for this conditional work.');}if(!evidence)errors.push('Add the actual deliverable, run or review reference.');const h=f.get('hours');if(h!==''&&(!Number.isFinite(Number(h))||Number(h)<0||Number(h)>24))errors.push('Actual time must be between 0 and 24 hours.');if(errors.length){$('outcome-error').textContent=errors.join(' ');return;}if(r.result)r.history.push({result:r.result,evidence:r.evidence,reviewer:r.reviewer,recordedAt:r.recordedAt});Object.assign(r,{result,evidence,reviewer,hours:h===''?'':Number(h),recordedAt:new Date().toISOString()});persist();render();toast(result+' recorded for Day '+selected+'. Review gates remain separate.');}
function modal(title,body,eyebrow='PROJECT RECORD'){ $('dialog-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h2 id="dialog-title">${esc(title)}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div><div class="dialog-content">${body}</div>`;$('dialog').showModal();}
function reviewModal(kind,id){const x=D[kind==='gate'?'gates':'stages'].find(x=>x.id===id),r=S[kind==='gate'?'gates':'stages'][id]||{};let issues=kind==='gate'?gateIssues(id):[...(!gateSatisfied(x.gate)?[x.gate+' has no applicable release']:[]),...x.requires.filter(y=>!stageSatisfied(y)).map(y=>y+' is not accepted')];modal(`${id} · ${x.name}`,`<div class="notice"><strong>Record an actual external disposition.</strong> A saved record is your report of a review, not approval issued by this website. Named qualified reviewers and current signed physical permits remain necessary.</div>${issues.length?`<div class="notice red"><strong>Current prerequisites</strong><ul class="blocker-list">${issues.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>PASS/release cannot be recorded while these remain unresolved.</div>`:''}<form id="review-form"><div class="outcome-grid"><label><span class="field-label">Actual disposition</span><select name="result" required><option value="">Choose result</option>${['PASS','REWORK','BLOCKED'].map(v=>`<option ${r.result===v?'selected':''}>${v}</option>`).join('')}</select></label><label><span class="field-label">Actual review date</span><input name="date" type="date" value="${esc(r.date||'')}" required max="${todayISO()}"></label><label><span class="field-label">Actual reviewer name</span><input name="reviewer" value="${esc(r.reviewer||'')}" required maxlength="200"></label><label><span class="field-label">Qualified role and review scope</span><input name="role" value="${esc(r.role||'')}" required maxlength="500"></label><label class="wide-field"><span class="field-label">Evidence / signed disposition reference</span><input name="evidence" value="${esc(r.evidence||'')}" required maxlength="1500" placeholder="Exact reviewed revision, permit or evidence packet"></label><label class="wide-field"><span class="field-label">Conditions and limitations</span><textarea name="notes" maxlength="12000">${esc(r.notes||'')}</textarea></label></div><h3>Confirm the evidence actually covers</h3>${x.checks.map((c,i)=>`<label class="check-row"><input name="c${i}" type="checkbox" ${r.checks?.[i]?'checked':''}><span>${esc(c)}</span></label>`).join('')}<label class="check-row"><input name="reviewed" type="checkbox" ${r.reviewed?'checked':''}><span>This disposition was actually made by the named authorized reviewer for this exact scope. I am recording it, not asking this website to grant permission.</span></label><p class="form-error" id="review-error" role="alert"></p><div class="button-row"><button class="button" type="submit">Save actual review record</button><button class="button ghost" type="button" data-action="open-day" data-day="${x.day}">Read target day ${x.day}</button></div></form>`,'RELEASES AND EVIDENCE');$('review-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),checks=x.checks.map((_,i)=>f.get('c'+i)==='on'),result=f.get('result'),reviewed=f.get('reviewed')==='on';if(result==='PASS'&&(issues.length||!checks.every(Boolean)||!reviewed)){$('review-error').textContent='PASS requires all actual evidence checks, an external disposition and all applicable prior releases. Resolve blockers or record REWORK/BLOCKED.';return;}const date=f.get('date');if(!validDate(date)||date>todayISO()){$('review-error').textContent='Use the date the review actually occurred; future approvals cannot be recorded.';return;}S[kind==='gate'?'gates':'stages'][id]={result,checks,reviewed,date,reviewer:f.get('reviewer').trim(),role:f.get('role').trim(),evidence:f.get('evidence').trim(),notes:f.get('notes').trim(),updatedAt:new Date().toISOString()};persist();$('dialog').close();render();toast('Actual '+id+' disposition recorded.');});}
function costModal(id){const base=D.budget.find(r=>r[0]===id),r=S.costs[id];modal(id+' · '+base[1],`<p>Projected total includes cash already spent on this line. Record confirmed zero actual spending as 0; blank means unknown. Whole-project cost uses at least the amount actually spent.</p><form id="cost-form"><div class="outcome-grid"><label><span class="field-label">Projected total USD</span><input type="number" name="forecast" min="0" max="1000000" step="0.01" value="${esc(r.forecast??'')}" required></label><label><span class="field-label">Actual cash spent USD</span><input type="number" name="actual" min="0" max="1000000" step="0.01" value="${esc(r.actual??'')}"></label><label><span class="field-label">Basis</span><select name="kind">${['allowance','quote','receipt','confirmed resource','reserve'].map(x=>`<option ${r.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="field-label">Source date</span><input name="date" type="date" value="${esc(r.updated||'')}" required max="${todayISO()}"></label><label class="wide-field"><span class="field-label">Quote / receipt / confirmed-resource reference</span><input name="reference" value="${esc(r.reference)}" required maxlength="1500"></label></div><p class="section-description">No order is placed here. A zero-cost reuse still needs actual ownership, suitability and associated costs documented. A reserve needs a recorded rationale.</p><p class="form-error" id="cost-error"></p><button class="button" type="submit">Save budget line</button></form>`,'COST INPUT');$('cost-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),forecast=Number(f.get('forecast')),a=f.get('actual');if(!Number.isFinite(forecast)||forecast<0)return;S.costs[id]={forecast,actual:a===''?null:Number(a),kind:f.get('kind'),reference:f.get('reference').trim(),updated:f.get('date')};persist();$('dialog').close();render();toast('Budget updated. Affected gate applicability has been rechecked.');});}
function massModal(id){const base=D.mass.find(r=>r[0]===id),r=S.masses[id];modal(id+' · '+base[1],`<p>Original allocation ${num(base[2],2)} kg. Enter a traceable estimate and a measured value only when each exists. Use kg and document calibration/configuration for measurements.</p><form id="mass-form"><div class="outcome-grid"><label><span class="field-label">Projected component mass kg</span><input name="estimate" type="number" min="0" max="500" step="0.001" value="${esc(r.estimate??'')}"></label><label><span class="field-label">Measured component mass kg</span><input name="measured" type="number" min="0" max="500" step="0.001" value="${esc(r.measured??'')}"></label><label><span class="field-label">Actual source date</span><input name="date" type="date" value="${esc(r.updated||'')}" required max="${todayISO()}"></label><label class="wide-field"><span class="field-label">CAD / vendor / calibrated measurement reference</span><input name="reference" value="${esc(r.reference||'')}" required maxlength="1500"></label></div><p class="section-description">Unassigned reserve has no physical mass or COM. Walking excludes the 2 kg test object; supported handling accounts for it separately.</p><div class="button-row"><button class="button" type="submit">Save mass contribution</button></div></form>`,'MASS INPUT');$('mass-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);S.masses[id]={estimate:f.get('estimate')===''?null:Number(f.get('estimate')),measured:f.get('measured')===''?null:Number(f.get('measured')),reference:f.get('reference').trim(),updated:f.get('date')};persist();$('dialog').close();render();toast('Mass updated. Affected gate applicability has been rechecked.');});}
function download(name,body,type='application/json'){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download('Baymax_365_Progress_'+todayISO()+'.json',JSON.stringify({format:'baymax365-progress',version:2,exportedAt:new Date().toISOString(),owner:'Faisal Farouq',state:S},null,2));toast('Backup downloaded. Keep it private and recoverable.');}
function dayMarkdown(){const d=D.days[selected-1],r=dayState(selected);return `# Day ${d.id}: ${d.title}\n\nDate ${isoDate(dateAt(d.id))} | Owner Faisal Farouq | R0.2\n\nObjective: ${d.objective}\nPlanned effort: ${d.minutes} min\nMode: ${d.mode}\n\n## Inputs\n${d.inputs.map(x=>'- '+x).join('\n')}\n\n## Exact steps\n${d.steps.map((s,i)=>`- [${r.steps[i]?'x':' '}] ${i+1}. (${d.stepMinutes[i]} min) ${s}`).join('\n\n')}\n\n## Completion checks\n${d.acceptance.map((s,i)=>`- [${r.checks[i]?'x':' '}] ${s}`).join('\n')}\n\nOutput: ${d.output}\nCalculation/check: ${d.calculation}\nStop: ${d.stop}\nRequired gates: ${d.gates.join(', ')||'None; ordinary task authority still applies'}\nPrior test stages: ${d.stages.join(', ')||'None'}\nNext dependency: ${d.next}\n\n## Blocked alternative\n${d.alternative.map(x=>'- '+x).join('\n')}\nOutput: ${d.alternativeOutput}\n\n## Actual record\nResult: ${r.result||'NOT RECORDED'}\nEvidence: ${r.evidence}\nActual hours: ${r.hours}\nRole/reviewer: ${r.reviewer}\nNotes: ${r.notes}\n\nTask completion does not grant engineering approval or validate the whole robot.\n`;}
document.addEventListener('change',e=>{if(!D)return;const target=e.target;if(target.matches('[data-step],[data-check]')){const r=dayState(selected);if(target.hasAttribute('data-step'))r.steps[Number(target.dataset.step)]=target.checked;else r.checks[Number(target.dataset.check)]=target.checked;persist();const active=target.id;const scroll=window.scrollY;render();window.scrollTo(0,scroll);if(active)$(active)?.focus({preventScroll:true});}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||!D)return;const a=b.dataset.action;if(a==='today')navigate('#day/'+calendarDay());if(a==='open-day'){if($('dialog').open)$('dialog').close();navigate('#day/'+b.dataset.day);window.scrollTo(0,0);}if(a==='download-day')download('Baymax_Day_'+String(selected).padStart(3,'0')+'.md',dayMarkdown(),'text/markdown');if(a==='copy-output'){try{await navigator.clipboard.writeText(D.days[selected-1].output);toast('File path copied.');}catch{toast('Copy the displayed file path using your browser.');}}if(a==='month'){planMonth=b.dataset.month;navigate('#plan');}if(a==='review')reviewModal(b.dataset.kind,b.dataset.id);if(a==='close-dialog')$('dialog').close();if(a==='backup')backup();if(a==='import')$('import-file').click();if(a==='cost')costModal(b.dataset.id);if(a==='mass')massModal(b.dataset.id);if(a==='requirement'){registryQuery=b.dataset.id;navigate('#register/requirements');}if(a==='artifact'){const x=D.artifacts.find(x=>x.number===Number(b.dataset.id));modal(x.title,`<p><strong>${esc(x.control.Result)}</strong><br>R0.1 · 23 October 2026 · Owner Faisal Farouq</p>${x.body.trim().split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}<h3>Task control</h3>${Object.entries(x.control).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(v)}</p>`).join('')}`,'ORIGINAL CONNECTED ARTIFACT');}});
function sanitizeImport(x){if(x?.format!=='baymax365-progress'||x.version!==2||x.state?.version!==2||!validDate(x.state.start))throw Error('This is not a supported Baymax 365 backup.');const n=blankState();n.start=x.state.start;for(const [id,r]of Object.entries(x.state.days||{})){if(!/^\d+$/.test(id)||Number(id)<1||Number(id)>365)continue;n.days[id]={steps:Array.from({length:6},(_,i)=>r.steps?.[i]===true),checks:Array.from({length:3},(_,i)=>r.checks?.[i]===true),notes:String(r.notes||'').slice(0,30000),result:['PASS','REWORK','BLOCKED'].includes(r.result)?r.result:'',evidence:String(r.evidence||'').slice(0,1500),reviewer:String(r.reviewer||'').slice(0,1000),hours:typeof r.hours==='number'&&r.hours>=0&&r.hours<=24?r.hours:'',recordedAt:String(r.recordedAt||'').slice(0,30),history:Array.isArray(r.history)?r.history.slice(-100):[]};}for(const kind of ['gates','stages'])for(const def of D[kind]){const r=x.state[kind]?.[def.id];if(!r)continue;n[kind][def.id]={result:['PASS','REWORK','BLOCKED'].includes(r.result)?r.result:'',checks:def.checks.map((_,i)=>r.checks?.[i]===true),reviewed:r.reviewed===true,date:validDate(r.date)?r.date:'',reviewer:String(r.reviewer||'').slice(0,200),role:String(r.role||'').slice(0,500),evidence:String(r.evidence||'').slice(0,1500),notes:String(r.notes||'').slice(0,12000)};}for(const id of Object.keys(n.costs)){const r=x.state.costs?.[id];if(!r)continue;n.costs[id]={forecast:typeof r.forecast==='number'&&r.forecast>=0?r.forecast:null,actual:typeof r.actual==='number'&&r.actual>=0?r.actual:null,kind:['allowance','quote','receipt','confirmed resource','reserve'].includes(r.kind)?r.kind:'allowance',reference:String(r.reference||'').slice(0,1500),updated:validDate(r.updated)?r.updated:''};}for(const id of Object.keys(n.masses)){const r=x.state.masses?.[id];if(!r)continue;n.masses[id]={estimate:typeof r.estimate==='number'&&r.estimate>=0?r.estimate:null,measured:typeof r.measured==='number'&&r.measured>=0?r.measured:null,reference:String(r.reference||'').slice(0,1500),updated:validDate(r.updated)?r.updated:''};}return n;}
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5_000_000)throw Error('Backup is larger than the 5 MB import limit.');const imported=sanitizeImport(JSON.parse(await file.text()));modal('Replace this browser’s progress?',`<p>The selected backup contains ${Object.values(imported.days).filter(r=>r.result).length} recorded daily outcomes. Export your current progress first if you need to preserve it. Imported review records remain self-recorded evidence references, not newly validated approvals.</p><div class="button-row"><button class="button ghost" data-action="backup">Export current backup</button><button class="button" id="confirm-import">Replace with selected backup</button></div>`,'IMPORT CONFIRMATION');$('confirm-import').addEventListener('click',()=>{S=imported;persist();$('dialog').close();render();toast('Backup imported. Prerequisite applicability has been rechecked.');});}catch(err){toast('Import not applied: '+err.message);}});
$('export-backup').addEventListener('click',()=>D&&backup());$('settings-button').addEventListener('click',()=>navigate('#settings'));$('mobile-menu').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);});
fetch('plan.json').then(r=>{if(!r.ok)throw Error('Plan could not load');return r.json();}).then(data=>{D=data;S=load();if(!location.hash)history.replaceState(null,'','#day/1');route();if(!storageOK)toast('Storage unavailable. Export progress before leaving.');}).catch(err=>{$('main').innerHTML=`<div class="panel panel-body"><h1>The daily plan could not open</h1><p class="section-description">${esc(err.message)}. Reload this page or open the downloaded plan from the project package.</p><button class="button" onclick="location.reload()">Reload plan</button></div>`;});
})();
